{
  "findings": [
    {
      "check_id": "CKV_AZURE_229",
      "title": "Azure SQL Database is not zone redundant",
      "resource": "azurerm_mssql_database.trading_database",
      "severity": "MEDIUM",
      "explanation": "The database has 'zone_redundant' explicitly set to false, which reduces high availability and disaster recovery capabilities by not distributing replicas across multiple Availability Zones."
    }
  ],
  "patched_code": "resource \"azurerm_mssql_database\" \"trading_database\" {\n  name           = \"trading-database\"\n  server_id      = azurerm_mssql_server.trading_sql_server.id\n  collation      = \"SQL_Latin1_General_CP1_CI_AS\"\n  license_type   = \"LicenseIncluded\"\n  max_size_gb    = 100\n  sku_name       = \"S2\"\n  zone_redundant = true\n}",
  "fix_summary": "Changed the 'zone_redundant' attribute from false to true to enable zone redundancy for improved high availability and disaster recovery."
}
